  __opt_text_some: { kind: "set", add_sql: `INSERT INTO "__opt_text_some" ("id", "value") VALUES (?, ?) ON CONFLICT ("value") DO UPDATE SET "id" = excluded."id"`, del_sql: `DELETE FROM "__opt_text_some" WHERE "id" = ? AND "value" = ?` },
